from PIL import Image, ImageEnhance, ImageChops


class ImageProcessor:
    def __init__(self):
        self._image = None

    @property
    def image(self):
        return self._image

    @image.setter
    def image(self, img):
        self._image = img

    def load_image(self, image_path):
        self.image = Image.open(image_path)

    def save_image(self, save_path):
        if self.image:
            self._save(self.image, save_path)

    def _save(self, image, save_path):
        if image:
            image.save(save_path)

    def resize_image(self, width, height):
        if self.image:
            self.image = self._resize(self.image, width, height)

    def _resize(self, image, width, height):
        return image.resize((width, height))

    def rotate_image(self, degrees):
        if self.image:
            self.image = self._rotate(self.image, degrees)

    def _rotate(self, image, degrees):
        return image.rotate(degrees)

    def adjust_brightness(self, factor):
        if self.image:
            self.image = self._enhance_brightness(self.image, factor)

    def _enhance_brightness(self, image, factor):
        enhancer = ImageEnhance.Brightness(image)
        return enhancer.enhance(factor)
